const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
// The 4.x Contacts editor (contact-editor.js, generated by docs/holo-contact-editor.py for 4.0.4, 4.3 and 4.4.4).
for(const v of ['4.0.4','4.3','4.4.4']){
  const ctx={window:{}};vm.runInNewContext(fs.readFileSync(`versions/${v}/contact-editor.js`,'utf8'),ctx);
  const H=ctx.window.HoloContactEditor;
  // An older contact (one phone / email / company) opens with its name split and typed rows.
  const d=H.fromPerson({id:1,name:'Alex Morgan',phone:'202-555-0148',email:'alex@example.com',company:'Gadget Weekly'},['friends']);
  assert.equal(d.given,'Alex',v);assert.equal(d.family,'Morgan',v);assert.equal(JSON.stringify(d.phones),JSON.stringify([{type:'mobile',value:'202-555-0148'}]),v);assert.equal(d.open.org,true,v);
  let html=H.render({lang:'en',draft:d,groups:[{id:'friends',name:'Friends'}],photoUrl:()=>''});
  assert.match(html,/Phone-only, unsynced contact/,v);assert.match(html,/data-action="hce-type" data-id="phones:0">Mobile</,v);assert.match(html,/>Add new</,v);assert.match(html,/>Add another field</,v);
  assert.match(html,/ce-ic_menu_remove_field_holo_light/,v);assert.doesNotMatch(html,/name="prefix"/,v);
  for(const [,src] of html.matchAll(/src="assets\/([^"]+)"/g))assert.ok(fs.existsSync(`versions/${v}/assets/${src}`),v+src);
  assert.match(H.render({lang:'hu',draft:d,groups:[],photoUrl:()=>''}),/Csak a telefonon, nem szinkronizált/,v);
  // Expanding the name, adding a phone with a type, a custom label, opening another kind, removing it.
  const ui={},c={draft:d,ui,form:null,render(){},renderOverlay(){}};
  H.handle('hce-expand','',c);assert.match(H.render({lang:'en',draft:d,groups:[],photoUrl:()=>''}),/name="prefix"[^>]*placeholder="Name prefix"/,v);
  H.handle('hce-add','phones',c);d.phones[1].value='+36 1 555 0100';H.handle('hce-set-type','phones:1:work',c);assert.equal(d.phones[1].type,'work',v);
  H.handle('hce-set-type','phones:1:custom',c);assert.equal(ui.hceDialog,'label:phones:1',v);H.submitLabel({get:k=>({label:'Office',target:'phones:1'})[k]},c);assert.equal(H.typeName('en',d.phones[1]),'Office',v);
  H.handle('hce-open','websites',c);assert.equal(d.websites.length,1,v);d.websites[0].value='example.com';
  ui.hceDialog='more';assert.doesNotMatch(H.overlay({lang:'en',draft:d,dialog:'more',photos:[],photoUrl:()=>''}),/>Website</,v);
  H.handle('hce-remove','phones:0',c);assert.equal(d.phones.length,1,v);H.handle('hce-remove','phones:0',c);assert.equal(d.phones.length,1,'Phone keeps one empty row');
  d.phones[0].value='202-555-0199';H.handle('hce-photo-set','7',c);assert.equal(d.photo,7,v);
  // Saving: the display name and the first phone / email stay as name / phone / email for Phone and Messaging.
  const person=H.toPerson(d,{id:1});
  assert.equal(person.name,'Alex Morgan',v);assert.equal(person.phone,'202-555-0199',v);assert.equal(person.email,'alex@example.com',v);assert.equal(person.photo,7,v);assert.equal(person.websites.map(x=>x.value).join(),'example.com',v);
  // The detail rows: every phone with its type and its own number for Call, the organization and website.
  const rows=H.details({...person,phones:[{type:'mobile',value:'1'},{type:'work',value:'2'}]},'en','stat_notify_sms.png');
  assert.match(rows,/data-number="2">2<small>Work</,v);assert.match(rows,/Gadget Weekly/,v);assert.match(rows,/example\.com/,v);
  // Photo choices and the type list come from the framework / Contacts texts.
  assert.match(H.overlay({lang:'en',draft:d,dialog:'photo',photos:[],photoUrl:()=>''}),/Take photo.*Choose photo from Gallery.*Remove photo/s,v);
  assert.match(H.overlay({lang:'de',draft:d,dialog:'type:phones:0',photos:[],photoUrl:()=>''}),/Mobil/,v);
  // people.js uses the editor and its detail rows; no glyph stars or Done text button of its own.
  const people=fs.readFileSync(`versions/${v}/people.js`,'utf8');assert.match(people,/HoloContactEditor\.render/,v);assert.match(people,/HoloContactEditor\.details/,v);assert.doesNotMatch(people,/[★☆]/,v);
}
console.log('contact-editor ok');
